func:
// === Lecture brute des entités HA (climatisation / chauffage gratuits) ===
// Getters + suivi de disponibilité des sondes. Pas de logique métier ici.
// PREREQUIS : cocher "Enable global context store" sur le nœud serveur HA.
// Toutes les entités sont réglables par les variables d'environnement de
// l'onglet (bouton ≡ → Flows → Climatisation Solaire → Env).

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

let g;
try {
    g = global.get('homeassistant').homeAssistant.states;
    if (!g) throw new Error('states indisponibles');
} catch (e) {
    node.warn('HA indisponible, tick ignoré : ' + e.message);
    return null;
}

const eStr = (k, def) => {
    const v = env.get(k);
    return (v === undefined || v === null || v === '') ? def : String(v);
};
const eNum = (k, def) => {
    const v = parseFloat(env.get(k));
    return isNaN(v) ? def : v;
};
const n = (id, def = 0) => {
    const v = parseFloat(g[id]?.state);
    return isNaN(v) ? def : v;
};
const numOrNull = (id) => {
    const raw = g[id]?.state;
    if (raw === undefined || raw === 'unavailable' || raw === 'unknown') return null;
    const v = parseFloat(raw);
    return isNaN(v) ? null : v;
};
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

// --- Entités ---
msg.climEntity = eStr('CLIM_ENTITY', 'climate.clim');
const indoorId = eStr('CLIM_INDOOR_SENSOR', 'sensor.temp_salon_temperature');
const outdoorId = eStr('CLIM_OUTDOOR_SENSOR', 'sensor.temp_exterieur_temperature');
const climPowerId = eStr('CLIM_POWER_SENSOR', 'sensor.clim_power');
const solarId = eStr('SOLAR_SENSOR', 'sensor.powermeter_power_a');
const gridId = eStr('GRID_SENSOR', 'sensor.powermeter_power_b');
msg.cumulusSensor = eStr('CUMULUS_SENSOR', 'sensor.cumulus_automation');

// --- Constantes du modèle ---
msg.climLoadW = clamp(eNum('CLIM_LOAD_W', 800), 100, 10000);
msg.cumulusLoadW = clamp(eNum('CUMULUS_LOAD_W', 1200), 100, 10000);
msg.minRunMs = clamp(eNum('CLIM_MIN_RUN_MIN', 20), 0, 240) * 60000;
msg.minOffMs = clamp(eNum('CLIM_MIN_OFF_MIN', 15), 0, 240) * 60000;
msg.hystMs = clamp(eNum('CLIM_HYST_MIN', 5), 1, 60) * 60000;
msg.stopRatio = clamp(eNum('CLIM_STOP_RATIO', 0.75), 0, 1);
msg.storeBand = clamp(eNum('CLIM_STORE_BAND', 1.5), 0, 6);
msg.coolFloor = eNum('CLIM_COOL_FLOOR', 21);
msg.heatCeiling = eNum('CLIM_HEAT_CEILING', 23);
msg.outdoorCoolMin = eNum('CLIM_OUTDOOR_COOL_MIN', 24);
msg.outdoorHeatMax = eNum('CLIM_OUTDOOR_HEAT_MAX', 17);

// --- Paramètres utilisateur (helpers HA) ---
msg.enabled = g['input_boolean.clim_automation_enabled']?.state === 'on';
msg.targetCool = clamp(n('input_number.clim_target_cool', 25), 18, 32);
msg.targetHeat = clamp(n('input_number.clim_target_heat', 20), 12, 26);

// Seuil de surplus requis pour démarrer. Défaut : puissance de la clim, donc
// aucun watt pris au réseau. Helper absent ou à 0 → défaut.
const trigRaw = numOrNull('input_number.clim_surplus_trigger');
msg.surplusTrig = (trigRaw != null && trigRaw > 0) ? Math.round(trigRaw) : Math.round(msg.climLoadW);

// Mode saison (helper optionnel) : auto / froid / chaud / arrêt
const SEASON_MAP = {
    auto: 'auto', froid: 'froid', chaud: 'chaud', 'arrêt': 'arret', arret: 'arret',
    cool: 'froid', heat: 'chaud', off: 'arret'
};
const seasonRaw = String(g['input_select.clim_season_mode']?.state || 'auto').toLowerCase();
msg.seasonMode = SEASON_MAP[seasonRaw] || 'auto';

// --- Sondes de température ---
msg.indoorTemp = numOrNull(indoorId);
msg.indoorAvailable = msg.indoorTemp != null;
msg.outdoorTemp = numOrNull(outdoorId);
msg.outdoorAvailable = msg.outdoorTemp != null;

// Suivi d'indisponibilité de la sonde intérieure (notification)
const nowMs = Date.now();
if (msg.indoorAvailable) {
    setF('sondeDownSince', null);
    msg.sondeDownHours = 0;
} else {
    let ds = getF('sondeDownSince');
    if (!ds) { ds = nowMs; setF('sondeDownSince', ds); }
    msg.sondeDownHours = Math.round((nowMs - ds) / 360000) / 10;
}

// --- Mesures électriques ---
msg.solar = n(solarId, 0);
msg.gridPower = n(gridId, 0);   // > 0 import réseau, < 0 injection
msg.surplus = -msg.gridPower;
msg.climPower = n(climPowerId, 0);

// --- État de la climatisation ---
// Pas de coercition 'unavailable' → 'off' : au reboot HA l'entité passe par
// des états transitoires. Repli sur le dernier état connu, comme le flow
// cumulus, pour éviter une fausse détection de pilotage manuel.
const climState = g[msg.climEntity];
const rawHvac = climState?.state;
msg.climAvailable = rawHvac !== undefined && rawHvac !== 'unavailable' && rawHvac !== 'unknown';
msg.hvacMode = msg.climAvailable ? rawHvac : (getF('lastKnownHvac') || 'off');
if (msg.climAvailable) setF('lastKnownHvac', rawHvac);
msg.climOn = msg.hvacMode !== 'off';
msg.hvacAction = climState?.attributes?.hvac_action || null;
const spRaw = parseFloat(climState?.attributes?.temperature);
msg.climSetpoint = isNaN(spRaw) ? null : spRaw;
msg.hvacModes = climState?.attributes?.hvac_modes || [];

// --- Cumulus : lecture du sensor du flow eau chaude (priorité absolue) ---
const cu = g[msg.cumulusSensor];
msg.cumulusFound = !!cu;
const ca = (cu && cu.attributes) || {};
msg.cumulus = {
    enabled: ca.enabled === true,
    desired: ca.desired || null,
    currentSwitch: ca.current_switch || null,
    power: parseFloat(ca.cumulus_power),
    waterTemp: parseFloat(ca.water_temp),
    reachFor: parseFloat(ca.reach_for),
    solarCoversTarget: ca.solar_covers_target === true,
    antiInjection: ca.anti_injection_useful === true || ca.anti_injection_active === true,
    legionellaPending: ca.legionella_critical_pending === true || ca.legionella_critical === true,
    thermostatTripped: ca.thermostat_tripped === true,
    manualHold: ca.manual_hold_active === true
};

return msg;

// === Détection du pilotage manuel de la climatisation ===
// Deux garde-fous distincts :
//  - PROPRIÉTÉ : une clim allumée à la main n'est jamais coupée par le flow
//    (climOwned = false, aucune commande d'arrêt). Le confort demandé par
//    l'utilisateur reste prioritaire sur l'économie.
//  - PAUSE : tout changement d'état non commandé par le flow met
//    l'automatisation en pause 45 min (même principe que le flow cumulus).
// États non exploitables (unavailable/unknown, typiquement au reboot HA)
// ignorés par la détection, sinon chaque redémarrage déclencherait une
// fausse intervention manuelle.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const MANUAL_HOLD_MS = 45 * 60 * 1000;
const HA_LAG_GRACE_MS = 90 * 1000;   // tolérance de propagation d'état HA
const now = Date.now();

let expected = getF('expectedHvac');
if (expected == null && msg.climAvailable) {
    expected = msg.hvacMode;
    setF('expectedHvac', expected);
}
const prevActionAt = getF('lastActionAt') || 0;
let holdUntil = getF('manualHoldUntil') || 0;
let owned = getF('climOwned') === true;

if (msg.climAvailable && expected != null
    && msg.hvacMode !== expected
    && (now - prevActionAt) > HA_LAG_GRACE_MS) {
    holdUntil = now + MANUAL_HOLD_MS;
    setF('manualHoldUntil', holdUntil);
    expected = msg.hvacMode;
    setF('expectedHvac', expected);
    owned = false;                       // reprise en main par l'utilisateur
    setF('climOwned', false);
    node.warn('Pilotage manuel de la clim détecté → pause automatisation 45 min');
}

// Clim à l'arrêt : plus rien à revendiquer
if (!msg.climOn && owned) {
    owned = false;
    setF('climOwned', false);
}

msg.climOwned = owned;
msg.manualHoldActive = msg.enabled && now < holdUntil;
msg.manualHoldUntil = holdUntil > now ? holdUntil : null;
// Clim en marche sans que le flow l'ait allumée : hors de son périmètre
msg.manualControl = msg.climOn && !owned;

// Libellés prêts à afficher (le nœud de décision se contente de les recopier)
if (msg.manualControl) {
    msg.manualLabel = 'Pilotage manuel';
    msg.manualReason = 'Climatisation allumée hors automatisation, arrêt non commandé';
} else if (msg.manualHoldActive) {
    msg.manualLabel = 'Pause (commande manuelle)';
    msg.manualReason = 'Intervention manuelle détectée, reprise à '
        + new Date(holdUntil).toLocaleTimeString('fr-FR');
}

return msg;

// === Priorité absolue à l'eau chaude ===
// Le surplus solaire finance d'abord le cumulus : la climatisation ne dispose
// que du reliquat. Deux situations à ne pas confondre, sous peine de compter
// deux fois la même énergie :
//   - cumulus DÉJÀ en chauffe : sa consommation est déjà retirée du surplus
//     mesuré au compteur réseau, aucune réservation supplémentaire ;
//   - cumulus à l'arrêt avec un besoin d'eau chaude non couvert : sa puissance
//     est RÉSERVÉE, la clim ne doit pas manger le surplus qui lui permettra de
//     démarrer (son hystérésis met 5 min à conclure).
// Sensor cumulus absent ou illisible : réservation par défaut, l'eau chaude ne
// perd jamais son surplus à cause d'une lecture manquante.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const CUMULUS_MIN_POWER_W = 100;
const CLIM_MIN_POWER_W = 50;
const STARTUP_GRACE_MS = 90 * 1000;   // compresseur + compteur lent

const now = Date.now();
const c = msg.cumulus || {};

// --- Consommation propre de la clim ---
// Nécessaire pour raisonner en surplus « potentiel » (surplus qu'on aurait si
// la clim était à l'arrêt), seule base stable pour décider d'un arrêt.
const lastAction = getF('lastAction');
const lastActionAt = getF('lastActionAt') || 0;
const justStarted = lastAction === 'on' && msg.climOn
    && (now - lastActionAt) < STARTUP_GRACE_MS;

let climDraw;
if (!msg.climOn) {
    climDraw = 0;
} else if (msg.climPower >= CLIM_MIN_POWER_W) {
    climDraw = msg.climPower;            // mesure réelle
} else if (justStarted) {
    climDraw = msg.climLoadW;            // démarrage, compteur pas rafraîchi
} else {
    climDraw = 0;                        // compresseur au repos (consigne atteinte)
}
msg.climDraw = Math.round(climDraw);
msg.climIdle = msg.climOn && climDraw === 0;

const potentialSurplus = msg.surplus + climDraw;
msg.potentialSurplus = Math.round(potentialSurplus);

// --- Réservation eau chaude ---
let reserve = 0;
let reason;
if (!msg.cumulusFound) {
    reserve = msg.cumulusLoadW;
    reason = 'sensor cumulus introuvable, réservation par sécurité';
} else if (!c.enabled) {
    reserve = 0;
    reason = 'automatisation cumulus désactivée';
} else if (!isNaN(c.power) && c.power >= CUMULUS_MIN_POWER_W) {
    reserve = 0;
    reason = 'cumulus en chauffe, consommation déjà déduite du surplus mesuré';
} else if (c.thermostatTripped && c.currentSwitch === 'on') {
    reserve = 0;
    reason = 'thermostat mécanique du cumulus ouvert, aucune consommation possible';
} else if (c.manualHold) {
    reserve = 0;
    reason = 'cumulus en pause manuelle';
} else if (c.desired === 'on') {
    reserve = msg.cumulusLoadW;
    reason = 'cumulus commandé ON, démarrage imminent';
} else if (c.antiInjection) {
    reserve = msg.cumulusLoadW;
    reason = 'anti-injection cumulus actif';
} else if (c.legionellaPending) {
    reserve = msg.cumulusLoadW;
    reason = 'cycle anti-légionelle en attente';
} else if (c.solarCoversTarget) {
    reserve = 0;
    reason = 'cible eau chaude couverte par le cumulus solaire amont';
} else if (isNaN(c.waterTemp) || isNaN(c.reachFor)) {
    reserve = msg.cumulusLoadW;
    reason = 'température d\'eau illisible, réservation par sécurité';
} else if (c.waterTemp < c.reachFor) {
    reserve = msg.cumulusLoadW;
    reason = 'eau à ' + c.waterTemp + '°C sous la cible ' + c.reachFor + '°C';
} else {
    reserve = 0;
    reason = 'eau chaude à la cible, surplus libéré pour le confort';
}

msg.cumulusReserveW = Math.round(reserve);
msg.cumulusReserveReason = reason;
msg.hotWaterPriority = reserve > 0;

// --- Surplus réellement disponible pour la clim ---
msg.availableW = Math.round(potentialSurplus - reserve);
// Préemption : le surplus aurait suffi au confort, la réservation eau chaude
// le lui retire. C'est le cas à afficher, distinct d'un simple manque de soleil.
msg.preemptedByHotWater = reserve > 0
    && potentialSurplus > msg.surplusTrig
    && msg.availableW < msg.surplusTrig;

// --- Estimation de l'énergie consommée par les cycles du flow (jour) ---
const lastSampleAt = getF('lastSampleAt');
let dtMs = lastSampleAt ? now - lastSampleAt : 0;
if (dtMs < 0 || dtMs > 10 * 60000) dtMs = 0;   // reprise après coupure : pas d'extrapolation
setF('lastSampleAt', now);

const dayKey = new Date(now).toISOString().slice(0, 10);
if (getF('energyDay') !== dayKey) {
    setF('energyDay', dayKey);
    setF('climWhToday', 0);
}
let wh = getF('climWhToday') || 0;
if (msg.climOwned && climDraw > 0) wh += climDraw * (dtMs / 3600000);
setF('climWhToday', wh);
msg.climKwhToday = Math.round(wh / 10) / 100;

return msg;

// === Besoin de confort et sens de fonctionnement (froid / chaud) ===
// Cible « gratuite » = confort de base réglé par l'utilisateur, avec un
// dépassement volontaire (CLIM_STORE_BAND) pour stocker l'énergie gratuite
// dans l'inertie du bâtiment, exactement comme le cumulus sert de batterie
// thermique. Dépassement borné par CLIM_COOL_FLOOR / CLIM_HEAT_CEILING, pour
// éviter l'inconfort inverse.
// Mode latché pendant un cycle : pas de bascule froid ↔ chaud en cours de route.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

msg.needMode = 'none';        // 'cool' | 'heat' | 'none'
msg.comfortTarget = null;
msg.storeTarget = null;
msg.needReason = null;

if (!msg.indoorAvailable) {
    msg.needReason = 'Sonde intérieure indisponible';
    setF('modeLatch', null);
    return msg;
}
if (msg.seasonMode === 'arret') {
    msg.needReason = 'Mode saison sur arrêt';
    setF('modeLatch', null);
    return msg;
}

const t = msg.indoorTemp;
const outdoor = msg.outdoorAvailable ? msg.outdoorTemp : null;

// Sens autorisé : forcé par le mode saison, ou déduit de l'extérieur en auto.
// Sonde extérieure absente : les deux sens restent possibles, l'écart intérieur
// tranche seul.
const canCool = msg.seasonMode === 'froid'
    || (msg.seasonMode === 'auto' && (outdoor == null || outdoor >= msg.outdoorCoolMin));
const canHeat = msg.seasonMode === 'chaud'
    || (msg.seasonMode === 'auto' && (outdoor == null || outdoor <= msg.outdoorHeatMax));

// Cibles de stockage (bornées par les garde-fous de confort)
const coolStore = Math.max(msg.targetCool - msg.storeBand, msg.coolFloor);
const heatStore = Math.min(msg.targetHeat + msg.storeBand, msg.heatCeiling);

const latch = getF('modeLatch');
const running = msg.climOn === true;

let mode = 'none';
if (canCool && t > msg.targetCool) {
    mode = 'cool';
} else if (canHeat && t < msg.targetHeat) {
    mode = 'heat';
} else if (running && latch === 'cool' && canCool && t > coolStore) {
    mode = 'cool';               // poursuite du cycle jusqu'à la cible de stockage
} else if (running && latch === 'heat' && canHeat && t < heatStore) {
    mode = 'heat';
}

if (mode === 'cool') {
    msg.comfortTarget = msg.targetCool;
    msg.storeTarget = Math.round(coolStore * 10) / 10;
    msg.needReason = t > msg.targetCool
        ? 'Intérieur ' + t + '°C au-dessus de la cible froid ' + msg.targetCool + '°C'
        : 'Stockage de fraîcheur jusqu\'à ' + msg.storeTarget + '°C';
} else if (mode === 'heat') {
    msg.comfortTarget = msg.targetHeat;
    msg.storeTarget = Math.round(heatStore * 10) / 10;
    msg.needReason = t < msg.targetHeat
        ? 'Intérieur ' + t + '°C sous la cible chaud ' + msg.targetHeat + '°C'
        : 'Stockage de chaleur jusqu\'à ' + msg.storeTarget + '°C';
} else if (!canCool && !canHeat) {
    msg.needReason = 'Saison neutre'
        + (outdoor != null ? ' (extérieur ' + outdoor + '°C)' : '');
} else {
    msg.needReason = 'Confort déjà assuré (' + t + '°C, cibles '
        + msg.targetHeat + '–' + msg.targetCool + '°C)';
}

msg.needMode = mode;
msg.canCool = canCool;
msg.canHeat = canHeat;
setF('modeLatch', mode === 'none' ? null : mode);

return msg;

// === Hystérésis du surplus + protection anti court-cycle ===
// Démarrage : surplus disponible (après réservation eau chaude) au-dessus du
// seuil pendant CLIM_HYST_MIN. Arrêt : sous le seuil d'arrêt pendant la même
// durée. Entre les deux, zone morte : aucun changement, les nuages passagers
// ne font pas claquer le compresseur.
// Anti court-cycle : ni démarrage avant CLIM_MIN_OFF_MIN d'arrêt, ni arrêt
// avant CLIM_MIN_RUN_MIN de marche (usure du compresseur).
// Échappatoire : import réseau franc (surplus disponible ≤ 0) pendant plus de
// HARD_STOP_MS → arrêt immédiat malgré la temporisation. C'est ce qui rend la
// priorité eau chaude effective même en plein cycle.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const HARD_STOP_MS = 2 * 60 * 1000;
const now = Date.now();

const trig = msg.surplusTrig;
const stopTrig = Math.round(trig * msg.stopRatio);
msg.stopTrigger = stopTrig;

let highSince = getF('highSurplusSince');
let lowSince = getF('lowSurplusSince');

if (msg.availableW > trig) {
    if (!highSince) { highSince = now; setF('highSurplusSince', now); }
    setF('lowSurplusSince', null);
    msg.surplusHigh = (now - highSince) > msg.hystMs;
    msg.surplusLow = false;
} else if (msg.availableW < stopTrig) {
    if (!lowSince) { lowSince = now; setF('lowSurplusSince', now); }
    setF('highSurplusSince', null);
    msg.surplusHigh = false;
    msg.surplusLow = (now - lowSince) > msg.hystMs;
} else {
    setF('highSurplusSince', null);
    setF('lowSurplusSince', null);
    msg.surplusHigh = false;
    msg.surplusLow = false;
}

// --- Arrêt d'urgence sur import réseau soutenu ---
let hardSince = getF('hardStopSince');
if (msg.availableW <= 0) {
    if (!hardSince) { hardSince = now; setF('hardStopSince', now); }
    msg.hardStop = (now - hardSince) > HARD_STOP_MS;
} else {
    setF('hardStopSince', null);
    msg.hardStop = false;
}

// --- Anti court-cycle ---
const lastOnAt = getF('lastOnAt') || 0;
const lastOffAt = getF('lastOffAt') || 0;
msg.canStart = !msg.climOn && (now - lastOffAt) >= msg.minOffMs;
msg.canStop = msg.climOn && (now - lastOnAt) >= msg.minRunMs;
msg.minRunLeftMin = msg.climOn
    ? Math.max(0, Math.ceil((msg.minRunMs - (now - lastOnAt)) / 60000)) : 0;
msg.minOffLeftMin = !msg.climOn
    ? Math.max(0, Math.ceil((msg.minOffMs - (now - lastOffAt)) / 60000)) : 0;

// Verdict surplus : en marche, on continue tant que rien ne dit d'arrêter ;
// à l'arrêt, il faut un surplus confirmé pour démarrer.
msg.surplusOk = msg.climOn
    ? !(msg.surplusLow || msg.hardStop)
    : msg.surplusHigh === true;

return msg;

// === Maintien : état conservé, aucune commande de changement ===
// Quatre cas, tous légitimes : cycle en cours qui se poursuit, arrêt différé
// par la protection compresseur, démarrage différé pour la même raison,
// attente d'un surplus suffisant.

msg.desired = msg.climOn ? 'on' : 'off';

if (msg.climOn) {
    if (!msg.surplusOk) {
        msg.state = 'Arrêt différé (anti court-cycle)';
        msg.reason = (msg.preemptedByHotWater
            ? 'Surplus repris par l\'eau chaude (' + msg.cumulusReserveW + ' W réservés)'
            : 'Surplus insuffisant')
            + ', arrêt possible dans ' + msg.minRunLeftMin + ' min (protection compresseur)';
    } else {
        msg.state = msg.needMode === 'cool' ? 'Rafraîchissement gratuit' : 'Chauffage gratuit';
        msg.reason = 'Surplus solaire ' + msg.availableW + ' W disponible après eau chaude'
            + (msg.climIdle ? ', compresseur au repos (consigne atteinte)' : '');
    }
} else if (msg.surplusOk) {
    msg.state = 'Démarrage différé (anti court-cycle)';
    msg.reason = 'Surplus disponible, redémarrage possible dans '
        + msg.minOffLeftMin + ' min (protection compresseur)';
} else if (msg.preemptedByHotWater) {
    msg.state = 'Veille (eau chaude prioritaire)';
    msg.reason = 'Surplus de ' + msg.potentialSurplus + ' W réservé au cumulus ('
        + msg.cumulusReserveReason + ')';
} else {
    msg.state = 'Veille (surplus insuffisant)';
    msg.reason = 'Surplus disponible ' + msg.availableW + ' W, seuil de démarrage '
        + msg.surplusTrig + ' W';
}

return msg;

// === Détermine l'action, tient l'historique ===
// action = 'start' (mode + consigne) / 'adjust' (réalignement) / 'stop' / 'none'
// Règle de sécurité : une clim allumée à la main n'est jamais coupée par le
// flow (climOwned = false → arrêt non commandé, simple affichage).

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const now = Date.now();
const SETPOINT_TOL = 0.2;

msg.action = 'none';
msg.targetHvac = msg.needMode === 'cool' ? 'cool' : msg.needMode === 'heat' ? 'heat' : 'off';

// Toutes les unités n'exposent pas 'cool'/'heat' (certaines n'ont que
// 'heat_cool' ou 'auto'). Commande envoyée seulement si le mode existe, sinon
// elle échouerait en boucle. Liste vide (entité injoignable) : pas de blocage.
const modes = Array.isArray(msg.hvacModes) ? msg.hvacModes : [];
msg.modeSupported = msg.targetHvac === 'off' || modes.length === 0
    || modes.indexOf(msg.targetHvac) !== -1;

// Entité injoignable : aucune commande, elle échouerait et fausserait
// l'historique (grace period et détection manuelle dérivent ensuite).
if (!msg.climAvailable) {
    msg.reason = (msg.reason || '') + ' · clim injoignable, aucune commande';
} else if (msg.desired === 'on' && !msg.climOn) {
    if (!msg.modeSupported) {
        msg.state = 'Mode non supporté';
        msg.reason = msg.climEntity + ' n\'expose pas le mode ' + msg.targetHvac
            + ' (modes disponibles : ' + modes.join(', ') + ')';
    } else {
        msg.action = 'start';
        setF('lastOnAt', now);
        setF('lastActionAt', now);
        setF('lastAction', 'on');
        setF('lastActionReason', msg.reason);
        setF('expectedHvac', msg.targetHvac);
        setF('climOwned', true);
        msg.climOwned = true;
    }
} else if (msg.desired === 'off' && msg.climOn) {
    if (msg.climOwned) {
        msg.action = 'stop';
        setF('lastOffAt', now);
        setF('lastActionAt', now);
        setF('lastAction', 'off');
        setF('lastActionReason', msg.reason);
        setF('expectedHvac', 'off');
        setF('climOwned', false);
        msg.climOwned = false;
    } else {
        msg.state = 'Pilotage manuel';
        msg.reason = 'Climatisation allumée hors automatisation, arrêt non commandé';
    }
} else if (msg.desired === 'on' && msg.climOn && msg.climOwned
    && msg.targetHvac !== 'off' && msg.modeSupported) {
    // Cycle en cours : réalignement si le mode ou la consigne a dérivé
    // (bascule froid/chaud, cible modifiée par l'utilisateur).
    const modeDrift = msg.hvacMode !== msg.targetHvac;
    const spDrift = msg.storeTarget != null
        && (msg.climSetpoint == null || Math.abs(msg.climSetpoint - msg.storeTarget) > SETPOINT_TOL);
    if (modeDrift || spDrift) {
        msg.action = 'adjust';
        setF('lastActionAt', now);
        setF('expectedHvac', msg.targetHvac);
        msg.reason = msg.reason + ' · réalignement '
            + (modeDrift ? 'mode ' + msg.targetHvac : 'consigne ' + msg.storeTarget + '°C');
    }
}

msg.lastAction = getF('lastAction');
msg.lastActionAt = getF('lastActionAt');
msg.lastActionReason = getF('lastActionReason');
msg.now = now;

return msg;

// === Alertes HA (persistent_notification) ===
// Une notification par épisode, anti-spam par contexte persistant.

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const out = [];
const now = Date.now();
const DAY_MS = 24 * 3600 * 1000;

// 1. Sonde intérieure HS depuis ≥ 2 h
if ((msg.sondeDownHours || 0) >= 2) {
    if (!getF('notifSondeDown')) {
        setF('notifSondeDown', true);
        out.push({ payload: {
            notification_id: 'clim_sonde_hs',
            title: 'Clim : sonde intérieure HS',
            message: 'Sonde indisponible depuis ' + msg.sondeDownHours
                + ' h. Climatisation gratuite suspendue (pilotage à l\'aveugle exclu).'
        }});
    }
} else if (msg.indoorAvailable) {
    setF('notifSondeDown', false);
}

// 2. Sensor cumulus introuvable : la priorité eau chaude tourne en aveugle,
//    avec réservation permanente du surplus (clim quasi jamais autorisée).
if (msg.cumulusFound === false) {
    const last = getF('notifNoCumulusAt') || 0;
    if (now - last > DAY_MS) {
        setF('notifNoCumulusAt', now);
        out.push({ payload: {
            notification_id: 'clim_cumulus_absent',
            title: 'Clim : sensor cumulus introuvable',
            message: msg.cumulusSensor + ' absent. Surplus réservé en permanence à l\'eau '
                + 'chaude par sécurité, confort gratuit désactivé. Variable '
                + 'CUMULUS_SENSOR à vérifier.'
        }});
    }
}

// 3. Entité climatisation injoignable depuis ≥ 1 h
if (msg.climAvailable === false) {
    let since = getF('climDownSince');
    if (!since) { since = now; setF('climDownSince', now); }
    if (now - since > 3600 * 1000 && !getF('notifClimDown')) {
        setF('notifClimDown', true);
        out.push({ payload: {
            notification_id: 'clim_injoignable',
            title: 'Clim : entité injoignable',
            message: msg.climEntity + ' indisponible depuis plus d\'une heure, '
                + 'aucune commande envoyée.'
        }});
    }
} else {
    setF('climDownSince', null);
    setF('notifClimDown', false);
}

if (out.length === 0) return null;
return [out];

// === Gestion des erreurs du flow (nœud catch) ===

const STORE = 'file';
function getF(k) { try { return flow.get(k, STORE); } catch (e) { return flow.get(k); } }
function setF(k, v) { try { flow.set(k, v, STORE); } catch (e) { flow.set(k, v); } }

const src = (msg.error && msg.error.source) || {};
const SERVICE_NODES = ["c0f1000000000024", "c0f1000000000025", "c0f1000000000026"]; // set_hvac_mode / set_temperature / turn_off

// Commande clim échouée : l'historique optimiste est faux → purge, sinon la
// grace period de démarrage, l'anti court-cycle et la détection de pilotage
// manuel dérivent tous les trois.
if (SERVICE_NODES.indexOf(src.id) !== -1) {
    setF('lastAction', null);
    setF('lastActionAt', 0);
    setF('expectedHvac', null);
    setF('climOwned', false);
}

// Anti-spam : 1 notification max / 15 min
const now = Date.now();
const last = getF('lastErrorNotifAt') || 0;
if (now - last < 15 * 60 * 1000) return null;
setF('lastErrorNotifAt', now);

msg.payload = {
    notification_id: 'clim_flow_error',
    title: 'Clim : erreur dans le flow',
    message: (src.name || src.id || '?') + ' : '
        + (msg.error && msg.error.message ? msg.error.message : 'erreur inconnue')
};
return msg;
